请对以下 case 进行三维加权评分。

=== case_id ===
Case-15-smart-home-006

=== 用户原始指令 (query.txt) ===
帮我弄个用电的,占比百分比会变,点一下能跳进去看,从日历看日程,有红色报警

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "帮我弄个用电的,占比百分比会变,点一下能跳进去看,从日历看日程,有红色报警",
  "size": "2x2",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "com.huawei.hmos.settings",
        "abilityName": "com.huawei.hmos.settings.MainAbility",
        "uri": "battery"
      }
    }
  ],
  "dataModelSchema": {
    "data": {
      "power": {
        "title": {
          "type": "string",
          "description": "用电卡片标题",
          "sampleValue": "全屋用电"
        },
        "usagePercent": {
          "type": "number",
          "description": "当前用电占比数值，用于进度组件",
          "sampleValue": 72
        },
        "usagePercentText": {
          "type": "string",
          "description": "当前用电占比展示文本",
          "sampleValue": "72%"
        },
        "progressTotal": {
          "type": "number",
          "description": "用电占比进度总量",
          "sampleValue": 100
        },
        "caption": {
          "type": "string",
          "description": "用电占比说明",
          "sampleValue": "今日占比"
        },
        "alertText": {
          "type": "string",
          "description": "红色报警短状态",
          "sampleValue": "报警"
        },
        "alertReason": {
          "type": "string",
          "description": "用电报警原因短文本",
          "sampleValue": "超阈值"
        }
      },
      "calendar": {
        "items": [
          {
            "entityId": {
              "type": "string",
              "description": "日程唯一标识符",
              "sampleValue": "calendar-event-001"
            },
            "title": {
              "type": "string",
              "description": "今日日程标题",
              "sampleValue": "巡检"
            },
            "dtStart": {
              "type": "string",
              "description": "今日日程开始时间",
              "sampleValue": "20:30"
            },
            "dtEnd": {
              "type": "string",
              "description": "今日日程结束时间",
              "sampleValue": "21:00"
            }
          }
        ]
      }
    }
  },
  "assetCandidates": []
}

